Ext._define('rh.pvf.sendpointsheet.ReferenceWindow', {
    extend: 'core.RestfulWindow',
    rest: 'rh.pvf.sendpointsheet.Restful',
    
    actionTitles: {
        create: 'Folha Ponto',
        update: 'Editar',
        remove: 'Remover',
        read: 'Carregar'
    },

    getFormPanel: function(cfg) {
        if(!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                frame: true,
                items: [
                    this.getReference(),
                ]
            });

        return this._formPanel;
    },

    getButtons: function (cfg) {
        if (!this._buttons) 
            this._buttons = []
            this._buttons.push(
                new Ext._create('Ext.Button', {
                    text:"Criar Solicitação",
                    height: 28,
                    width:110,
                    scope: this,
                    handler: function () {
                        this.createPointSheet(cfg);
                    },
                    
                }),
                new Ext._create('Ext.Button', {
                    text: 'Fechar',
                    height: 28,
                    scope: this,
                    handler: function () {
                        this.close();
                    },
                    
                })
            )
        return this._buttons;
    },


    getReference: function() {
        if (!this._yearfield) {
            this._yearfield = Ext._create('core.fields.ComboField', {
                fieldLabel: "Selecione a referência",
                hiddenName: "year",
                anchor:'99%',
                // value:new Date().getFullYear(),
                displayField: 'description',
                store: Ext._create('Ext.data.Store', {
                    proxy: Ext._create('Ext.data.HttpProxy', {
                      url: core.callAction('PVFSendPointSheet', 'get_reference')
                    }),
                    reader: Ext._create('Ext.data.JsonReader', {
                        totalProperty: 'count',
                        root: 'collection',
                        fields: [
                            {name: 'pk', type: 'int'},
                            {name: 'description', type: 'string'},
                        ]
                    })
                }),
                autoLoad: true
            });
        }

        return this._yearfield;
    },


    createPointSheet: function(){
        if(this.getReference().getValue()){
            Ext.Ajax.request({
                url: toolkit.util.Normalize.controller_action('PVFSendPointSheet', 'save'),
                    params: {
                        reference: this.getReference().lastSelectionText
                    },
                    success: function (request) {
                        var obj = Ext.decode(request.responseText);
                        if (obj.success){
                            this.destroy();
                            var month = obj.month
                            var year = obj.year
                            var pk= obj.pk
                            var daily_workload = obj.daily_workload
                            this.ownerGrid.createItem('rh.pvf.sendpointsheet.Window',null,{
                                'pk':pk,
                                'month':month,
                                'year':year,
                                'daily_workload':daily_workload
                            })
                            this.ownerGrid.getStore().reload()
                        }else{
                            Ext.Msg.show({
                                title: 'Error',
                                msg: obj.message,
                                icon: Ext.Msg.ERROR,
                                buttons: Ext.Msg.OK
                            });
                        }     
                    },
                    failure: function (request) {
                        Ext.Msg.show({
                            msg: 'Ocorreu um erro tentando processar sua requisição, tente novamente mais tarde.',
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK
                        })
                    },
                    scope: this
            });
            }else Ext.Msg.show({
                msg: 'Selecione a referência da folha ponto que deseja criar.',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK
            })
	},


});
